contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint m, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (m)); require(m <= 1000000000000000000000000000000);
        require(m > 0);
        require(amount > 0);
        require(address(this).balance >= m);
        c.SetMinSum(m); if (__ESBMC_reverted()) return;
        c.Deposit{value: m}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherBefore = address(c).balance;
        c.Collect(amount); if (__ESBMC_reverted()) return;
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherAfter = address(c).balance;
        bool shouldWithdraw = balBefore >= m && balBefore >= amount;
        bool successCase = (!shouldWithdraw) || (balAfter == balBefore - amount && etherBefore - etherAfter == amount);
        bool failCase = shouldWithdraw || (balAfter == balBefore && etherAfter == etherBefore);
        assert(successCase && failCase);
    }
    receive() external payable {}
}

