pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 m, uint256 amount) internal {
        m = bound(m, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(m > 0);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= m);
        try c.SetMinSum(m) {} catch { return; }
        try c.Deposit{value: m}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint etherBefore = address(c).balance;
        try c.Collect(amount) {} catch { return; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint etherAfter = address(c).balance;
        bool shouldWithdraw = balBefore >= m && balBefore >= amount;
        bool successCase = (!shouldWithdraw) || (balAfter == balBefore - amount && etherBefore - etherAfter == amount);
        bool failCase = shouldWithdraw || (balAfter == balBefore && etherAfter == etherBefore);
        assertTrue(successCase && failCase);
    }

    function testFuzz_run(uint256 m, uint256 amount) public {
        _run(m, amount);
    }

    receive() external payable {}
}
